import time
import json
import redis
from sqlalchemy import create_engine, text
from app.infrastructure.database import SessionLocal

def analyze_db():
    print("--- 1. TIMESCALEDB QUERY PLAN TRACING ---")
    db = SessionLocal()
    try:
        # Raw SQL query generated by SQLAlchemy
        query = text("""
        EXPLAIN (ANALYZE, BUFFERS) 
        SELECT inventory_telemetry.recorded_at, inventory_telemetry.supplier_id, 
               inventory_telemetry.tracking_id, inventory_telemetry.sku_id, 
               inventory_telemetry.inventory_count, inventory_telemetry.delivery_delay_days, 
               inventory_telemetry.predicted_stockout_probability, inventory_telemetry.is_critical_risk 
        FROM inventory_telemetry 
        WHERE inventory_telemetry.supplier_id = 'NVIDIA Corporation' 
          AND inventory_telemetry.sku_id = 'SKU-NV-5090' 
        ORDER BY inventory_telemetry.recorded_at DESC 
        LIMIT 90
        """)
        
        result = db.execute(query).fetchall()
        for row in result:
            print(row[0])
            
        print("\n[Analysis Note]: Check if it's using an 'Index Scan' or 'Seq Scan'. Look for 'Index Scan using ix_inventory_telemetry_supplier_id' or a new index.")
    except Exception as e:
        print(f"DB Error: {e}")
    finally:
        db.close()

def analyze_redis():
    print("\n--- 2. REDIS NETWORK & SERIALIZATION PROFILING ---")
    try:
        # Check how it's instantiated. In app/main.py it uses aioredis.from_url("redis://localhost:6379/0") inside the listener.
        # But wait, aioredis is deprecated in modern redis-py, though it might be used. 
        # Using synchronous redis for benchmarking overhead:
        
        r = redis.Redis(host='redis', port=6379, db=0, socket_timeout=2.0)
        
        # 1. Ping Latency (50 iterations)
        start_time = time.perf_counter()
        for _ in range(50):
            r.ping()
        ping_latency = (time.perf_counter() - start_time) * 1000 / 50
        print(f"Average Ping Latency (network overhead): {ping_latency:.3f} ms")
        
        # 2. Raw String Set/Get Latency
        start_time = time.perf_counter()
        r.set('test', '1')
        r.get('test')
        r.delete('test')
        raw_latency = (time.perf_counter() - start_time) * 1000
        print(f"Raw String Set/Get Latency: {raw_latency:.3f} ms")
        
        # 3. Large Payload Serialization vs Transport
        payload_dict = {"data": "x" * (1024 * 1024)} # 1MB string
        
        # Serialization time
        ser_start = time.perf_counter()
        serialized_payload = json.dumps(payload_dict)
        serialization_time = (time.perf_counter() - ser_start) * 1000
        print(f"JSON Serialization Time (1MB dict): {serialization_time:.3f} ms")
        
        # Transport time
        trans_start = time.perf_counter()
        r.set('large_test', serialized_payload)
        fetched = r.get('large_test')
        transport_time = (time.perf_counter() - trans_start) * 1000
        print(f"Redis Transport Time (Set/Get 1MB payload): {transport_time:.3f} ms")
        r.delete('large_test')
        
    except Exception as e:
        print(f"Redis Error: {e}")

if __name__ == "__main__":
    analyze_db()
    analyze_redis()
